extends "res://htd/htd_test.gd"


func _run_tests() -> void:
	var validator = await instantiate_script("res://story/story_validator.gd")
	if not check("validator_creato", validator != null, "Lo script res://story/story_validator.gd deve esistere e potersi istanziare senza errori"):
		return

	if not check("ha_validate_chapter", has_function(validator, "validate_chapter"), "StoryValidator deve avere la funzione validate_chapter(file_path: String) -> Array[String]"):
		return

	# 1. Controllo storie corrette esistenti nel progetto
	var valid_stories: Array[String] = [
		"res://story/intro.json",
		"res://story/branching_story.json",
		"res://story/network_story.json",
		"res://story/consequence_story.json"
	]
	for path in valid_stories:
		var errs: Variant = validator.validate_chapter(path)
		if not check("valida_" + path.get_file(), errs is Array and (errs as Array).is_empty(), "La storia corretta %s non deve generare alcun errore (trovati: %s)" % [path, str(errs)]):
			return

	# 2. Controllo storia con personaggio sconosciuto
	var file_unknown_speaker := "user://test_unknown_speaker.json"
	var f1 := FileAccess.open(file_unknown_speaker, FileAccess.WRITE)
	f1.store_string(JSON.stringify({
		"lines": [
			{"type": "line", "speaker": "Mago", "text": "Chi osa disturbarmi?"}
		]
	}))
	f1.close()

	var errs_speaker: Array = validator.validate_chapter(file_unknown_speaker)
	var found_speaker := false
	for msg in errs_speaker:
		if String(msg).find("Mago") != -1:
			found_speaker = true
			break
	check("errore_speaker", found_speaker, "Il validatore deve segnalare l'errore per il personaggio sconosciuto 'Mago'")

	# 3. Controllo storia con salto verso etichetta inesistente
	var file_missing_jump := "user://test_missing_jump.json"
	var f2 := FileAccess.open(file_missing_jump, FileAccess.WRITE)
	f2.store_string(JSON.stringify({
		"lines": [
			{"type": "line", "speaker": "Elena", "text": "Avanziamo verso la stanza."},
			{"type": "jump", "target": "stanza_inesistente"}
		]
	}))
	f2.close()

	var errs_jump: Array = validator.validate_chapter(file_missing_jump)
	var found_jump := false
	for msg in errs_jump:
		if String(msg).find("stanza_inesistente") != -1:
			found_jump = true
			break
	check("errore_jump", found_jump, "Il validatore deve segnalare l'errore per il salto verso l'etichetta inesistente 'stanza_inesistente'")

	# 4. Controllo storia con scelta verso etichetta inesistente
	var file_missing_choice := "user://test_missing_choice.json"
	var f3 := FileAccess.open(file_missing_choice, FileAccess.WRITE)
	f3.store_string(JSON.stringify({
		"lines": [
			{"type": "choice", "options": [{"text": "Apri", "target": "porta_fantasma"}]}
		]
	}))
	f3.close()

	var errs_choice: Array = validator.validate_chapter(file_missing_choice)
	var found_choice := false
	for msg in errs_choice:
		if String(msg).find("porta_fantasma") != -1:
			found_choice = true
			break
	check("errore_scelta", found_choice, "Il validatore deve segnalare l'errore per l'opzione di scelta verso l'etichetta inesistente 'porta_fantasma'")

	# 5. Controllo storia con condizione su variabile mai impostata
	var file_unset_var := "user://test_unset_var.json"
	var f4 := FileAccess.open(file_unset_var, FileAccess.WRITE)
	f4.store_string(JSON.stringify({
		"lines": [
			{
				"type": "line",
				"speaker": "Marco",
				"text": "Hai la torcia accesa.",
				"condition": {"variable": "has_torch", "operator": "==", "value": true}
			}
		]
	}))
	f4.close()

	var errs_var: Array = validator.validate_chapter(file_unset_var)
	var found_var := false
	for msg in errs_var:
		if String(msg).find("has_torch") != -1:
			found_var = true
			break
	check("errore_variabile", found_var, "Il validatore deve segnalare l'errore per la variabile 'has_torch' mai impostata")

