class_name StoryInterpreter
extends Node

signal story_finished

@export var dialogue_box: PanelContainer
@export var character_stage: CharacterStage
@export var background_display: BackgroundDisplay
@export var choice_menu: ChoiceMenu

var _variables: Dictionary = {}


func get_variable(var_name: String, default: Variant = null) -> Variant:
	return _variables.get(var_name, default)


func set_variable(var_name: String, value: Variant) -> void:
	_variables[var_name] = value


func add_variable(var_name: String, amount: Variant) -> void:
	var current: Variant = _variables.get(var_name, 0)
	_variables[var_name] = current + amount


func clear_variables() -> void:
	_variables.clear()


func evaluate_condition(condition: Dictionary) -> bool:
	if condition.is_empty():
		return true

	var var_name: String = condition.get("variable", "")
	var op: String = condition.get("operator", "==")
	var target_value: Variant = condition.get("value", null)
	var current_value: Variant = _variables.get(var_name, null)

	match op:
		"==":
			return current_value == target_value
		"!=":
			return current_value != target_value
		">":
			return current_value != null and current_value > target_value
		"<":
			return current_value != null and current_value < target_value
		">=":
			return current_value != null and current_value >= target_value
		"<=":
			return current_value != null and current_value <= target_value
		_:
			return false


func run_story(commands: Array[Dictionary]) -> void:
	var labels: Dictionary = {}
	for i in range(commands.size()):
		var cmd: Dictionary = commands[i]
		if cmd.get("type", "") == "label":
			var label_id := String(cmd.get("id", ""))
			if not label_id.is_empty():
				labels[label_id] = i

	var index := 0
	while index < commands.size():
		var command: Dictionary = commands[index]

		if command.has("condition"):
			var cond: Variant = command.get("condition")
			if cond is Dictionary and not evaluate_condition(cond):
				index += 1
				continue

		var cmd_type: String = command.get("type", "")

		match cmd_type:
			"label":
				index += 1
			"jump":
				var target: String = command.get("target", "")
				if labels.has(target):
					index = labels[target]
				else:
					index += 1
			"choice":
				var options: Array = command.get("options", [])
				var valid_options: Array = []
				for option_data in options:
					if option_data is Dictionary:
						if option_data.has("condition"):
							var cond: Variant = option_data.get(
								"condition"
							)
							if cond is Dictionary and not evaluate_condition(cond):
								continue
						valid_options.append(option_data)

				if valid_options.is_empty():
					index += 1
				elif choice_menu:
					choice_menu.show_choices(valid_options)
					var selected_target: String = await choice_menu.choice_selected
					if labels.has(selected_target):
						index = labels[selected_target]
					else:
						index += 1
				else:
					index += 1
			_:
				await execute_command(command)
				index += 1


func execute_command(command: Dictionary) -> void:
	var command_type: String = command.get("type", "")

	match command_type:
		"line":
			await _cmd_line(command)
		"wait":
			await _cmd_wait(command)
		"set":
			var var_name: String = command.get("variable", "")
			var val: Variant = command.get("value", null)
			set_variable(var_name, val)
		"add":
			var var_name: String = command.get("variable", "")
			var val: Variant = command.get("value", 0)
			add_variable(var_name, val)
		_:
			pass


func _cmd_line(cmd: Dictionary) -> void:
	var speaker: String = cmd.get("speaker", "")
	var text: String = cmd.get("text", "")
	if dialogue_box and dialogue_box.has_method("show_line"):
		dialogue_box.show_line(speaker, text)
		if dialogue_box.has_signal("line_finished"):
			await dialogue_box.line_finished


func _cmd_wait(cmd: Dictionary) -> void:
	var duration: float = float(cmd.get("duration", 0.1))
	await get_tree().create_timer(duration).timeout

