@tool
class_name StoryValidator
extends EditorScript


func _run() -> void:
	print("--- Inizio controllo storie ---")
	var stories: Array[String] = [
		"res://story/intro.json",
		"res://story/branching_story.json",
		"res://story/network_story.json",
		"res://story/consequence_story.json"
	]
	var total_errors := 0
	for story_path in stories:
		var errors := validate_chapter(story_path)
		if errors.is_empty():
			print("OK: %s" % story_path)
		else:
			for err in errors:
				printerr(err)
				total_errors += 1
	if total_errors == 0:
		print("Tutte le storie sono corrette!")
	else:
		printerr("Trovati %d errori totali." % total_errors)
	print("--- Controllo terminato ---")


func validate_chapter(file_path: String) -> Array[String]:
	var errors: Array[String] = []
	if not FileAccess.file_exists(file_path):
		errors.append("%s: File non trovato." % file_path)
		return errors

	var file := FileAccess.open(file_path, FileAccess.READ)
	if not file:
		errors.append("%s: Impossibile aprire il file." % file_path)
		return errors

	var content: String = file.get_as_text()
	var json_data: Variant = JSON.parse_string(content)
	if not json_data is Dictionary:
		errors.append("%s: Il file non contiene un oggetto JSON valido." % file_path)
		return errors

	var chapter: Dictionary = json_data
	if not chapter.has("lines") or not chapter["lines"] is Array:
		errors.append("%s: La chiave 'lines' non è presente o non è una lista." % file_path)
		return errors

	var lines: Array = chapter["lines"]
	var known_speakers: Array[String] = ["Elena", "Marco", "???", ""]
	var declared_labels: Dictionary = {}
	var assigned_variables: Array[String] = []

	# 1. Prima passata: raccoglie etichette e variabili definite
	for i in range(lines.size()):
		var entry: Variant = lines[i]
		if not entry is Dictionary:
			continue
		var cmd: Dictionary = entry
		var cmd_type: String = String(cmd.get("type", ""))

		if cmd_type == "label":
			var label_name: String = String(cmd.get("id", cmd.get("name", "")))
			if label_name.is_empty():
				errors.append("%s [riga %d]: Etichetta senza nome specificato." % [file_path, i])
			elif declared_labels.has(label_name):
				errors.append("%s [riga %d]: Etichetta duplicata '%s'." % [file_path, i, label_name])
			else:
				declared_labels[label_name] = i

		if cmd_type == "set" or cmd_type == "add":
			var var_name: String = String(cmd.get("variable", ""))
			if not var_name.is_empty() and not assigned_variables.has(var_name):
				assigned_variables.append(var_name)

	# 2. Seconda passata: controlla personaggi, salti, scelte e condizioni
	for i in range(lines.size()):
		var entry: Variant = lines[i]
		if not entry is Dictionary:
			errors.append("%s [riga %d]: Elemento non valido nella lista comandi." % [file_path, i])
			continue

		var cmd: Dictionary = entry

		# Controllo speaker
		if cmd.has("speaker"):
			var speaker: String = String(cmd.get("speaker", ""))
			if not known_speakers.has(speaker):
				errors.append("%s [riga %d]: Personaggio sconosciuto '%s'." % [file_path, i, speaker])

		# Controllo salti
		var cmd_type: String = String(cmd.get("type", ""))
		if cmd_type == "jump":
			var target: String = String(cmd.get("target", ""))
			if target.is_empty() or not declared_labels.has(target):
				errors.append("%s [riga %d]: Salto verso etichetta inesistente '%s'." % [file_path, i, target])

		# Controllo scelte
		if cmd_type == "choice":
			var options: Variant = cmd.get("options", [])
			if options is Array:
				for opt_entry in options:
					if opt_entry is Dictionary:
						var opt: Dictionary = opt_entry
						var target: String = String(opt.get("target", ""))
						if target.is_empty() or not declared_labels.has(target):
							errors.append("%s [riga %d]: Scelta con salto verso etichetta inesistente '%s'." % [file_path, i, target])
						if opt.has("condition"):
							var cond: Variant = opt.get("condition")
							if cond is Dictionary:
								var var_name: String = String(cond.get("variable", ""))
								if not var_name.is_empty() and not assigned_variables.has(var_name):
									errors.append("%s [riga %d]: Condizione su variabile mai impostata '%s'." % [file_path, i, var_name])

		# Controllo condizioni su comandi generici
		if cmd.has("condition"):
			var cond: Variant = cmd.get("condition")
			if cond is Dictionary:
				var var_name: String = String(cond.get("variable", ""))
				if not var_name.is_empty() and not assigned_variables.has(var_name):
					errors.append("%s [riga %d]: Condizione su variabile mai impostata '%s'." % [file_path, i, var_name])

	return errors
